mapper.insert:
INSERT INTO FREE_BOARD_TBL (
BNO, USER_ID, TITLE,
CONTENT, REGDATE, VIEWCNT, YOUTUBE_URL, BOARD_IMAGE
) VALUES (
SEQ_FREE_BOARD.NEXTVAL, #{userId}, #{title}, #{content}, SYSDATE, 0,
#{youtubeUrl,
jdbcType=VARCHAR}, #{board_image, jdbcType=VARCHAR}
)

mapper.delete:
DELETE FROM FREE_BOARD_TBL
WHERE BNO = #{bno}
AND USER_ID
= #{userId}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT B.BNO, B.USER_ID AS userId, U.NICKNAME AS nickname, B.TITLE, B.CONTENT, B.REGDATE AS regdate, B.VIEWCNT AS viewcnt, B.YOUTUBE_URL AS youtubeUrl, (SELECT COUNT(*) FROM BOARD_LIKE_TBL L WHERE L.BNO = B.BNO) AS likeCount FROM FREE_BOARD_TBL B JOIN user_tbl U ON B.USER_ID = U.user_id
AND B.TITLE LIKE '%' || #{keyword} || '%' AND B.CONTENT LIKE '%' || #{keyword} || '%' AND U.NICKNAME LIKE '%' || #{keyword} || '%'
ORDER BY B.VIEWCNT DESC, B.BNO DESC ORDER BY likeCount DESC, B.BNO DESC ORDER BY B.BNO DESC
) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}
